// The mindmap preset [SPEC 8/12]: `|mindmap|` is the visible root topic and
// bundles `layout: tree; direction: bilateral; routing: natural`, the palette
// walk (one hue per first-level branch — red and grey skipped), the
// `.lini-level-N` depth ramp, and `max-width: 160` topic wrap. Branch wires
// are desugar-generated, so `lini desugar` prints them like any other link.

{
  // A topic stacks its card content by default [SPEC 11]; here the icon reads
  // as part of the title, so each branch card stays one line tall and the tier
  // sits level whether or not it carries a glyph.
  |topic| { direction: row; }
}

