#!/usr/bin/env python3
# harness: run both binaries over snippet cases; report mismatches
import sys, subprocess, os, tempfile, difflib
sys.path.insert(0, '/tmp/tree')
from lt import run, ORIG, MINE

def compare(src, args=()):
    a = run(src, args, ORIG)
    b = run(src, args, MINE)
    return a == b, a, b

def show(src, a, b, n=12):
    print('-' * 70)
    print(src)
    if a[2] != b[2]:
        print('  exit', a[2], b[2])
    if a[1] != b[1]:
        print('  stderr orig:', a[1][:300])
        print('  stderr mine:', b[1][:300])
    if a[0] != b[0]:
        d = list(difflib.unified_diff(a[0].split('\n'), b[0].split('\n'), lineterm='', n=0))
        for l in d[2:2 + n]:
            print('  ', l[:220])

def main(cases, args=(), verbose=True, n=12):
    bad = 0
    for src in cases:
        ok, a, b = compare(src, args)
        if not ok:
            bad += 1
            if verbose:
                show(src, a, b, n)
    print('OK %d / %d' % (len(cases) - bad, len(cases)))
    return bad

if __name__ == '__main__':
    # cases file: separated by lines of '====='
    path = sys.argv[1]
    txt = open(path).read()
    cases = [c.strip('\n') for c in txt.split('\n=====\n') if c.strip()]
    main(cases, n=int(os.environ.get('N', '12')))

