#!/usr/bin/env python3
# random tree generator + comparison
import sys, random
sys.path.insert(0, '/tmp/tree')
from h import compare, show

WORDS = ['Alpha', 'Beta', 'Gamma', 'Delta', 'Epsilon', 'Zeta', 'Eta', 'Theta', 'Iota', 'Kappa', 'Lambda', 'Mu',
         'Research', 'Ops', 'QA', 'X', 'Hiring', 'Marketing', 'Platform', 'Infra', 'Design', 'Docs', 'Support',
         'Sales', 'Legal', 'Finance', 'a', 'Mobile apps', 'Web', 'Data science team', 'API']

def label(rng, wrap):
    n = rng.choice([1, 1, 1, 2, 3]) if wrap else 1
    s = ' '.join(rng.choice(WORDS) for _ in range(n))
    if wrap and rng.random() < 0.15:
        s = s + '\\n' + rng.choice(WORDS)
    return s

def topic(rng, depth, maxd, wrap, ty='topic', extra=''):
    lab = label(rng, wrap)
    kids = []
    if depth < maxd:
        nk = rng.choice([0, 1, 1, 2, 2, 2, 3, 3, 4]) if depth > 0 else rng.choice([1, 2, 3, 4, 5])
        for _ in range(nk):
            kids.append(topic(rng, depth + 1, maxd, wrap))
    s = '|%s| "%s"%s' % (ty, lab, extra)
    if kids:
        s += ' [ ' + ' ; '.join(kids) + ' ]'
    return s

def case(rng):
    kind = rng.choice(['column', 'row', 'bilateral', 'mindmap', 'mindmap', 'mmcol', 'mmrow', 'inbox'])
    maxd = rng.choice([1, 2, 2, 3, 3, 4])
    if kind in ('column', 'row', 'bilateral'):
        gap = rng.choice(['', '', ' gap: 64 48;', ' gap: 80 60;', ' gap: 50;'])
        lab = rng.choice(['', '', ' "Caption"'])
        t = topic(rng, 0, maxd, rng.random() < 0.4)
        return '|column|%s { layout: tree; direction: %s;%s } [ %s ]' % (lab, kind, gap, t)
    if kind == 'mindmap':
        return topic(rng, 0, maxd, True, 'mindmap')
    if kind == 'mmcol':
        return topic(rng, 0, maxd, True, 'mindmap', ' { direction: column; }')
    if kind == 'mmrow':
        return topic(rng, 0, maxd, True, 'mindmap', ' { direction: row; }')
    return '|column| "Box" [ %s ]' % topic(rng, 0, maxd, True, 'mindmap')

if __name__ == '__main__':
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    n = int(sys.argv[2]) if len(sys.argv) > 2 else 50
    rng = random.Random(seed)
    bad = 0
    for i in range(n):
        src = case(rng)
        ok, a, b = compare(src)
        if not ok:
            bad += 1
            show(src, a, b, 8)
    print('OK %d / %d' % (n - bad, n))

