import sys, re, random, json, subprocess, os, tempfile, math
sys.path.insert(0, '/tmp/tree')
from lt import run, paths, ORIG, MINE
from gen import case

def f4(x):
    s = '%.4f' % x
    s = s.rstrip('0').rstrip('.')
    if s == '-0':
        s = '0'
    return s

def dbg(src):
    d = tempfile.mkdtemp(dir='/tmp/tree/s')
    p = os.path.join(d, 'r_in.lini')
    open(p, 'w').write(src)
    r = subprocess.run([MINE, 'r_in.lini'], capture_output=True, cwd=d, env=dict(os.environ, LINI_DBG_TREE='1'))
    os.remove(p); os.rmdir(d)
    return [json.loads(l[4:]) for l in r.stderr.decode().split('\n') if l.startswith('DBG ')]

SIDES = {'Right': (1, 0), 'Left': (-1, 0), 'Top': (0, -1), 'Bottom': (0, 1)}

def absc(chain, mode, k):
    # chain: leaf first. returns abs centre coordinate k (0=x,1=y)
    vals = [c[k] for c in chain]
    if mode == 'bu':
        t = 0.0
        for v in vals:
            t += v
        return t
    if mode == 'td':
        t = 0.0
        for v in reversed(vals):
            t += v
        return t

def side_pt(chain, side, mode):
    cx = absc(chain, mode, 0); cy = absc(chain, mode, 1)
    w, h = chain[0][2], chain[0][3]
    if side == 'Right': return (cx + w / 2, cy)
    if side == 'Left': return (cx - w / 2, cy)
    if side == 'Top': return (cx, cy - h / 2)
    return (cx, cy + h / 2)

def curve(s, e, sa, sb):
    ds = SIDES[sa]; de = SIDES[sb]
    s1 = (s[0] + ds[0] * 2, s[1] + ds[1] * 2)
    e1 = (e[0] + de[0] * 2, e[1] + de[1] * 2)
    dist = math.hypot(e1[0] - s1[0], e1[1] - s1[1])
    along = abs(e1[1] - s1[1]) if sa in ('Top', 'Bottom') else abs(e1[0] - s1[0])
    h = min(dist / 2, max(along, dist / 4))
    c1 = (s1[0] + ds[0] * h, s1[1] + ds[1] * h)
    c2 = (e1[0] + de[0] * h, e1[1] + de[1] * h)
    return [s, s1, c1, c2, e1, e]

def fmt(pts):
    s, s1, c1, c2, e1, e = pts
    return 'M %s %s L %s %s C %s %s %s %s %s %s L %s %s' % tuple(f4(v) for p in pts for v in p)

rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 3)
stats = {}
nsamp = 0
for i in range(60):
    src = case(rng)
    if 'mindmap' not in src:
        continue
    o, e, c = run(src)
    ps = [p for p in paths(o)]
    ds = dbg(src)
    if len(ps) != len(ds):
        continue
    for p, d in zip(ps, ds):
        if p.count(' C ') != 1:
            continue
        nsamp += 1
        for mode in ['bu', 'td']:
            for mode2 in ['bu', 'td']:
                s = side_pt(d['from'], d['sa'], mode)
                e = side_pt(d['to'], d['sb'], mode2)
                got = fmt(curve(s, e, d['sa'], d['sb']))
                key = mode + '/' + mode2
                stats.setdefault(key, 0)
                if got == p:
                    stats[key] += 1
print(nsamp, stats)

