def bez(P, t):
    mt = 1 - t
    return (mt**3*P[0][0] + 3*mt*mt*t*P[1][0] + 3*mt*t*t*P[2][0] + t**3*P[3][0],
            mt**3*P[0][1] + 3*mt*mt*t*P[1][1] + 3*mt*t*t*P[2][1] + t**3*P[3][1])

def rect_dist(p, r):
    x0, y0, x1, y1 = r
    dx = max(x0 - p[0], 0, p[0] - x1)
    dy = max(y0 - p[1], 0, p[1] - y1)
    return math.hypot(dx, dy)

def links(o):
    # (from, to, d)
    return re.findall(r'<g class="lini-link[^"]*" data-from="([^"]*)" data-to="([^"]*)">\s*<path d="([^"]*)"', o)

