import sys, re, random, os, subprocess, tempfile
sys.path.insert(0, '/tmp/tree')
from score2 import cases, run, ORIG, MINE

def f4(x):
    s = '%.4f' % x
    s = s.rstrip('0').rstrip('.')
    return '0' if s == '-0' else s

def dbg(src):
    d = tempfile.mkdtemp(dir='/tmp/tree/s')
    p = os.path.join(d, 'r_in.lini')
    open(p, 'w').write(src)
    r = subprocess.run([MINE, 'r_in.lini'], capture_output=True, cwd=d, env=dict(os.environ, LINI_DBG_TREE='1'))
    os.remove(p); os.rmdir(d)
    out = []
    for l in r.stderr.decode().split('\n'):
        if l.startswith('MID '):
            out.append(tuple(float(x) for x in l[4:].split()))
    return out

cands = {
    '(lo+hi)/2': lambda pe, far, k, d: ((pe + k * d) + (far - k * d)) / 2,
    '(pe+far)/2': lambda pe, far, k, d: (pe + far) / 2,
    'pe+(far-pe)/2': lambda pe, far, k, d: pe + (far - pe) / 2,
    'lo+(hi-lo)/2': lambda pe, far, k, d: (pe + k * d) + ((far - k * d) - (pe + k * d)) / 2,
    'pe*0.5+far*0.5': lambda pe, far, k, d: pe * 0.5 + far * 0.5,
    'lo*0.5+hi*0.5': lambda pe, far, k, d: (pe + k * d) * 0.5 + (far - k * d) * 0.5,
}
score = {k: 0 for k in cands}
total = 0
for kind in ['row', 'column', 'bilateral']:
    for src in cases(51, 60, [kind]):
        o = run(src, ORIG)
        mids = dbg(src)
        # original mid values: the x (row/bil) or y (column) of the first arc end of each Z path
        segs = re.findall(r'<path d="(M [^"]*)"', o[o.find('lini-links'):])
        omids = []
        for p in segs:
            v = re.findall(r'[A-Z]|-?[0-9.]+', p)
            if v.count('A') != 2:
                continue
            # M x0 y0 L x1 y1 A r r 0 0 s x2 y2 ...
            i = v.index('A')
            x2, y2 = v[i + 6], v[i + 7]
            x0, y0 = v[1], v[2]
            omids.append(x2 if y0 == v[5] else y2)
        mine_set = set()
        for m in mids:
            for name, f in cands.items():
                pass
        # match by value proximity
        for (pe, far, k, d) in mids:
            ref = (pe + far) / 2
            best = None
            for om in omids:
                if abs(float(om) - ref) < 0.01:
                    best = om
            if best is None:
                continue
            total += 1
            for name, f in cands.items():
                if f4(f(pe, far, k, d)) == best:
                    score[name] += 1
print(total, score)

