#!/usr/bin/env python3
# greedy reducer for tree snippets: drop topics while orig != mine persists
import sys, re
sys.path.insert(0, '/tmp/tree')
from lt import run, ORIG, MINE

def parse(s, i=0):
    # parse a list of topics: returns list of (label, kids), index
    items = []
    while i < len(s):
        m = re.match(r'\s*\|topic\| "((?:[^"\\]|\\.)*)"', s[i:])
        if not m:
            break
        label = m.group(1)
        i += m.end()
        kids = []
        m2 = re.match(r'\s*\[', s[i:])
        if m2:
            i += m2.end()
            kids, i = parse(s, i)
            m3 = re.match(r'\s*\]', s[i:])
            i += m3.end()
        items.append((label, kids))
        m4 = re.match(r'\s*;', s[i:])
        if m4:
            i += m4.end()
    return items, i

def render(items):
    out = []
    for label, kids in items:
        t = '|topic| "%s"' % label
        if kids:
            t += ' [ ' + render(kids) + ' ]'
        out.append(t)
    return ' ; '.join(out)

def paths_of(items, pre=()):
    res = []
    for k, (label, kids) in enumerate(items):
        p = pre + (k,)
        res.append(p)
        res += paths_of(kids, p)
