#!/usr/bin/env python3
# greedy reducer for tree snippets: drop topics while orig != mine persists
import sys, re
sys.path.insert(0, '/tmp/tree')
from lt import run, ORIG, MINE

def parse(s, i=0):
    # parse a list of topics: returns list of (label, kids), index
    items = []
    while i < len(s):
        m = re.match(r'\s*\|topic\| "((?:[^"\\]|\\.)*)"', s[i:])
        if not m:
            break
        label = m.group(1)
        i += m.end()
        kids = []
        m2 = re.match(r'\s*\[', s[i:])
        if m2:
            i += m2.end()
            kids, i = parse(s, i)
            m3 = re.match(r'\s*\]', s[i:])
            i += m3.end()
        items.append((label, kids))
        m4 = re.match(r'\s*;', s[i:])
        if m4:
            i += m4.end()
    return items, i

def render(items):
    out = []
    for label, kids in items:
        t = '|topic| "%s"' % label
        if kids:
            t += ' [ ' + render(kids) + ' ]'
        out.append(t)
    return ' ; '.join(out)

def paths_of(items, pre=()):
    res = []
    for k, (label, kids) in enumerate(items):
        p = pre + (k,)
        res.append(p)
        res += paths_of(kids, p)
    return res

def remove(items, path):
    if len(path) == 1:
        return items[:path[0]] + items[path[0] + 1:]
    k = path[0]
    label, kids = items[k]
    return items[:k] + [(label, remove(kids, path[1:]))] + items[k + 1:]

def bad(head, items, tail, pred):
    src = head + render(items) + tail
    a = run(src)
    b = run(src, (), MINE)
    return pred(a, b)

if __name__ == '__main__':
    src = open(sys.argv[1]).read()
    needle = sys.argv[2] if len(sys.argv) > 2 else None
    i = src.index('|topic|')
    j = src.rindex(']')
    # keep the outermost container brackets
    head = src[:i]
    body = src[i:j]
    tail = src[j:]
    items, _ = parse(body)
    def pred(a, b):
        if a == b:
            return False
        if needle:
            return needle in a[0]
        return True
    assert bad(head, items, tail, pred)
    changed = True
    while changed:
        changed = False
        for p in sorted(paths_of(items), key=len, reverse=True):
            try:
                cand = remove(items, p)
            except Exception:
                continue
            if not cand:
                continue
            if bad(head, cand, tail, pred):
                items = cand
                changed = True
                break
    print(head + render(items) + tail)

