1	// Trees and mindmaps on the compile side (`layout: tree`, `|mindmap|`).
2	//
3	// Building lowers a tree the way `lini desugar` prints it: a tree container
4	// (an explicit `layout: tree`, a node holding a |mindmap|, or the scene)
5	// gives its topics ids (`lini-topic-N` by sibling position), `.lini-level-N`
6	// depth classes, a side on a bilateral tree's first level and a palette hue
7	// per mindmap branch, and records the parent→child branch wires as links
8	// with anchored sides, in the statement order the desugared document has.
9	//
10	// Layout: levels stack along the growth axis in bands every topic of a
11	// level shares (both halves of a bilateral tree included), each topic
12	// centred in its band; across it siblings pack `gap`'s second value apart,
13	// a parent centred over its children's block. The container stacks the
14	// tree after its other content (that content reads backwards from the
15	// tree), the stack `gap`'s second value apart.
16	//
17	// Wires: natural curves run side centre to side centre; an orthogonal fan
18	// shares one trunk port on the parent, which slides off the centre only to
19	// let a child that faces the parent drop straight.
20	
21	use crate::ast::{Decl, NodeStmt, Stmt, Term};
22	use crate::compile::Ctx;
23	use crate::route::{Rect, Side};
24	use crate::scene::{Builder, Link, Node};
25	use std::cell::RefCell;
26	use std::collections::{BTreeSet, HashMap};
27	
28	pub static HUES: &[&str] = &["rose", "orange", "amber", "lime", "green", "teal", "sky", "blue", "purple"];
29	
30	// How the children of a tree container or topic lower.
31	#[derive(Clone, Debug)]
32	struct Mode {
33	    // hues on the first level
34	    mindmap: bool,
35	    dir: String,
36	    // the level the children take
37	    level: usize,
38	    side: Option<String>,
39	    hue: Option<String>,
40	    tree: usize,
41	    // the children sit inside a mindmap (its descendant rules reach them)
42	    in_mm: bool,
43	}
44	
45	struct Frame {
46	    node: usize,
47	    mode: Mode,
48	    // tree nodes met so far among the children, and their count
49	    k: usize,
50	    n: usize,
51	    // the first mindmap's direction went to the container
52	    hoisted: bool,
53	    // so did its routing
54	    drop_routing: bool,
55	}
56	
57	#[derive(Clone, Debug, Default)]
58	pub struct TreeBox {
59	    pub dir: String,
60	    pub roots: Vec<usize>,
61	}
62	
63	#[derive(Clone, Debug)]
64	pub struct Topic {
65	    pub tree: usize,
66	    // the tree's root topic
67	    pub root: usize,
68	    pub level: usize,
69	    pub side: Option<String>,
70	    pub hue: Option<String>,
71	    pub mindmap: bool,
72	    pub kids: Vec<usize>,
73	}
74	
75	// A branch wire statement waiting for its place: the topic and its parent.
76	struct Pending {
77	    topic: usize,
78	}
79	
80	#[derive(Default)]
81	struct State {
82	    frames: Vec<Frame>,
83	    boxes: Vec<TreeBox>,
84	    box_of: HashMap<usize, usize>,
85	    topics: HashMap<usize, Topic>,
86	    // link index → the wire's hue (None: a plain branch wire)
87	    branches: HashMap<usize, Option<String>>,
88	    deferred: Vec<Pending>,
89	    mindmap_used: bool,
90	    levels: BTreeSet<usize>,
91	    hues: BTreeSet<String>,
92	    // each laid-out topic's centre relative to its tree's root
93	    at: HashMap<usize, (f64, f64)>,
94	    // topics given a generated id
95	    generated: std::collections::HashSet<usize>,
96	    // the scene tree's content size (its frame is built round it)
97	    root_content: Option<(f64, f64)>,
98	}
99	
100	thread_local! {
101	    static ST: RefCell<State> = RefCell::new(State::default());
102	}
103	
104	// ------------------------------------------------------------ queries
105	
106	// The scene tree's frame: its content padded twice over, each side by its
107	// own padding (x0, y0, w, h).
108	pub fn root_frame(pad: [f64; 4]) -> Option<(f64, f64, f64, f64)> {
109	    let (cw, ch) = ST.with(|s| s.borrow().root_content)?;
110	    let w = cw + 2.0 * (pad[1] + pad[3]);
111	    let h = ch + 2.0 * (pad[0] + pad[2]);
112	    Some((-w / 2.0 - (pad[3] - pad[1]), -h / 2.0 - (pad[0] - pad[2]), w, h))
113	}
114	
115	pub fn is_container(i: usize) -> bool {
116	    ST.with(|s| s.borrow().box_of.contains_key(&i))
117	}
118	
119	pub fn tree_box(i: usize) -> Option<TreeBox> {
120	    ST.with(|s| {
121	        let s = s.borrow();
122	        s.box_of.get(&i).map(|&b| s.boxes[b].clone())
123	    })
124	}
125	
126	pub fn topic(i: usize) -> Option<Topic> {
127	    ST.with(|s| s.borrow().topics.get(&i).cloned())
128	}
129	
130	pub fn is_topic_node(i: usize) -> bool {
131	    ST.with(|s| s.borrow().topics.contains_key(&i))
132	}
133	
134	// A child topic: laid out beside its parent topic, not inside it.
135	pub fn detached(ctx: &Ctx, i: usize) -> bool {
136	    match ctx.nodes[i].parent {
137	        Some(p) => ST.with(|s| {
138	            let s = s.borrow();
139	            s.topics.contains_key(&i) && s.topics.contains_key(&p)
140	        }),
141	        None => false,
142	    }
143	}
144	
145	// a topic whose id the tree made (`lini-topic-N`)
146	pub fn generated_id(i: usize) -> bool {
147	    ST.with(|s| s.borrow().generated.contains(&i))
148	}
149	
150	pub fn is_branch(li: usize) -> bool {
151	    ST.with(|s| s.borrow().branches.contains_key(&li))
152	}
153	
154	pub fn branch_hue(li: usize) -> Option<String> {
155	    ST.with(|s| s.borrow().branches.get(&li).cloned().flatten())
156	}
157	
158	// ------------------------------------------------------------ building
159	
160	fn chain_has(chain: &[String], t: &str) -> bool {
161	    chain.iter().any(|c| c == t)
162	}
163	
164	fn stmt_chain(b: &Builder, ns: &NodeStmt) -> Vec<String> {
165	    let t = ns.type_name.clone().unwrap_or_else(|| "box".to_string());
166	    crate::scene::type_chain(b.sheet, &t).map(|x| x.1).unwrap_or_default()
167	}
168	
169	fn own(decls: Option<&Vec<Decl>>, name: &str) -> Option<String> {
170	    let ds = decls?;
171	    let d = ds.iter().rev().find(|d| d.name == name)?;
172	    match d.value.groups.first().and_then(|g| g.first()) {
173	        Some(Term::Ident(s, _)) => Some(s.clone()),
174	        Some(Term::Str(s, _)) => Some(s.clone()),
175	        Some(Term::Num(_, s, _)) => Some(s.clone()),
176	        _ => None,
177	    }
178	}
179	
180	fn is_mindmap_stmt(b: &Builder, s: &Stmt) -> bool {
181	    match s {
182	        Stmt::Node(n) => chain_has(&stmt_chain(b, n), "mindmap"),
183	        _ => false,
184	    }
185	}
186	
187	fn tree_stmt(b: &Builder, s: &Stmt, mode: &Mode) -> bool {
188	    match s {
189	        Stmt::Node(n) => {
190	            let c = stmt_chain(b, n);
191	            if mode.level == 0 && mode.mindmap {
192	                chain_has(&c, "mindmap")
193	            } else {
194	                chain_has(&c, "topic")
195	            }
196	        }
197	        _ => false,
198	    }
199	}
200

200	
201	// the direction the first mindmap among `stmts` hands its container
202	fn mindmap_dir(b: &Builder, stmts: &[Stmt]) -> Option<String> {
203	    for s in stmts {
204	        if let Stmt::Node(n) = s {
205	            if chain_has(&stmt_chain(b, n), "mindmap") {
206	                return own(n.style.as_ref(), "direction");
207	            }
208	        }
209	    }
210	    None
211	}
212	
213	// the routing the first mindmap among `stmts` hands its container
214	fn mindmap_routing(b: &Builder, stmts: &[Stmt]) -> Option<String> {
215	    for s in stmts {
216	        if let Stmt::Node(n) = s {
217	            if chain_has(&stmt_chain(b, n), "mindmap") {
218	                return own(n.style.as_ref(), "routing");
219	            }
220	        }
221	    }
222	    None
223	}
224	
225	fn decl(name: &str, value: &str) -> Decl {
226	    let text: &'static str = Box::leak(format!("{}: {};", name, value).into_boxed_str());
227	    crate::style::parse_decls(text).into_iter().next().unwrap()
228	}
229	
230	fn decls(text: &str) -> Vec<Decl> {
231	    let text: &'static str = Box::leak(text.to_string().into_boxed_str());
232	    crate::style::parse_decls(text)
233	}
234	
235	// the decls a tree container gains
236	fn container_decls(inline: &mut Vec<Decl>, explicit: bool, dir: &str, mindmaps: bool, routing: Option<&str>) {
237	    if !explicit || mindmaps {
238	        for (k, v) in [("layout", "tree"), ("direction", dir), ("routing", routing.unwrap_or("natural"))] {
239	            if !inline.iter().any(|d| d.name == k) {
240	                inline.push(decl(k, v));
241	            }
242	        }
243	    }
244	    if !inline.iter().any(|d| d.name == "gap") {
245	        inline.push(decl("gap", "64 48"));
246	    }
247	}
248	
249	fn new_box(st: &mut State, node: usize, dir: &str) -> usize {
250	    st.boxes.push(TreeBox { dir: dir.to_string(), roots: vec![] });
251	    let b = st.boxes.len() - 1;
252	    st.box_of.insert(node, b);
253	    b
254	}
255	
256	// The scene as a tree: `layout: tree` at the root, or mindmaps at the top.
257	pub fn begin(b: &mut Builder, stmts: &[Stmt]) {
258	    ST.with(|s| *s.borrow_mut() = State::default());
259	    let root = &b.sheet.root;
260	    let layout = root.iter().rev().find(|d| d.name == "layout").and_then(|d| crate::style::ident_of(&d.value).map(|s| s.to_string()));
261	    let own_dir = root.iter().rev().find(|d| d.name == "direction").and_then(|d| crate::style::ident_of(&d.value).map(|s| s.to_string()));
262	    let has_mm = stmts.iter().any(|s| is_mindmap_stmt(b, s));
263	    let (explicit, dir, hoisted, mindmap_root) = if layout.as_deref() == Some("tree") {
264	        let hoisted = has_mm && own_dir.is_none();
265	        let dir = if hoisted {
266	            mindmap_dir(b, stmts).unwrap_or_else(|| "bilateral".into())
267	        } else {
268	            own_dir.clone().unwrap_or_else(|| "column".into())
269	        };
270	        (true, dir, hoisted, has_mm)
271	    } else if layout.is_none() && has_mm {
272	        let hoisted = own_dir.is_none();
273	        let dir = match &own_dir {
274	            Some(d) => d.clone(),
275	            None => mindmap_dir(b, stmts).unwrap_or_else(|| "bilateral".into()),
276	        };
277	        (false, dir, hoisted, true)
278	    } else {
279	        return;
280	    };
281	    // the root's decls: a tree's gap, a mindmap's direction and routing
282	    let user = |k: &str| root.iter().any(|d| d.name == k);
283	    let routing = if mindmap_root && !explicit && !user("routing") { mindmap_routing(b, stmts) } else { None };
284	    let mut fix: Vec<Decl> = vec![decl("layout", "tree")];
285	    if !user("gap") {
286	        fix.push(decl("gap", "64 48"));
287	    }
288	    if mindmap_root {
289	        if !user("direction") {
290	            fix.push(decl("direction", &dir));
291	        }
292	        if !user("routing") {
293	            fix.push(decl("routing", routing.as_deref().unwrap_or("natural")));
294	        }
295	    }
296	    for d in fix {
297	        let inl = &mut b.nodes[0].inline;
298	        match inl.iter_mut().find(|e| e.name == d.name) {
299	            Some(e) => *e = d,
300	            None => inl.push(d),
301	        }
302	    }
303	    ST.with(|s| {
304	        let mut st = s.borrow_mut();
305	        let tree = new_box(&mut st, 0, &dir);
306	        let mode = Mode { mindmap: !explicit, dir, level: 0, side: None, hue: None, tree, in_mm: false };
307	        let n = stmts.iter().filter(|s| tree_stmt(b, s, &mode)).count();
308	        st.frames.push(Frame { node: 0, mode, k: 0, n, hoisted, drop_routing: routing.is_some() });
309	    });
310	}
311	
312	// Before a node is added: a tree node takes its id and classes; a tree
313	// container opens a frame for its children.
314	pub fn enter(b: &Builder, ns: &NodeStmt, chain: &[String], parent: usize, n: &mut Node) {
315	    let i = b.nodes.len();
316	    let is_mm = chain_has(chain, "mindmap");
317	    ST.with(|s| {
318	        let mut st = s.borrow_mut();
319	        if is_mm {
320	            st.mindmap_used = true;
321	        }
322	        let top = st.frames.len().checked_sub(1).filter(|&f| st.frames[f].node == parent);
323	        if let Some(fi) = top {
324	            let mode = st.frames[fi].mode.clone();
325	            let tree_node = if mode.level == 0 && mode.mindmap { is_mm } else { chain_has(chain, "topic") };
326	            if tree_node {
327	                let k = st.frames[fi].k;
328	                st.frames[fi].k += 1;
329	                let half = (st.frames[fi].n + 1) / 2;
330	                let level = mode.level;
331	                let side = if mode.dir == "bilateral" {
332	                    if level == 1 {
333	                        Some(own(ns.style.as_ref(), "side").unwrap_or_else(|| if k < half { "right".into() } else { "left".into() }))
334	                    } else {
335	                        mode.side.clone()
336	                    }
337	                } else {
338	                    None
339	                };
340	                let hue = if mode.mindmap {
341	                    if level == 1 {
342	                        Some(HUES[k % HUES.len()].to_string())
343	                    } else {
344	                        mode.hue.clone()
345	                    }
346	                } else {
347	                    None
348	                };
349	                let drop_dir = st.frames[fi].hoisted && level == 0 && is_mm;
350	                if drop_dir {
351	                    st.frames[fi].hoisted = false;
352	                    n.inline.retain(|d| d.name != "direction");
353	                }
354	                if st.frames[fi].drop_routing && level == 0 && is_mm {
355	                    st.frames[fi].drop_routing = false;
356	                    n.inline.retain(|d| d.name != "routing");
357	                }
358	                let mindmap = mode.mindmap || is_mm;
359	                if n.id.is_none() {
360	                    n.id = Some(format!("lini-topic-{}", k + 1));
361	                    st.generated.insert(i);
362	                }
363	                if level == 1 && mode.dir == "bilateral" {
364	                    if let Some(sd) = &side {
365	                        n.tags.push(format!("side-{}", sd));
366	                    }
367	                    n.inline.retain(|d| d.name != "side");
368	                }
369	                n.tags.push(format!("level-{}", level));
370	                if level >= 1 {
371	                    st.levels.insert(level);
372	                }
373	                if mindmap {
374	                    if let Some(h) = &hue {
375	                        n.tags.push(format!("hue-{}", h));
376	                        st.hues.insert(h.clone());
377	                    }
378	                }
379	                if mode.in_mm {
380	                    n.tags.push("@mm".to_string());
381	                }
382	                let child = Mode {
383	                    mindmap,
384	                    dir: mode.dir.clone(),
385	                    level: level + 1,
386	                    side: side.clone(),
387	                    hue: hue.clone(),
388	                    tree: mode.tree,
389	                    in_mm: mode.in_mm || is_mm,
390	                };
391	                let cn = ns.children.as_ref().map_or(0, |c| c.iter().filter(|s| tree_stmt(b, s, &child)).count());
392	                let root = if level == 0 { i } else { st.topics.get(&parent).map_or(i, |t| t.root) };
393	                st.topics.insert(i, Topic { tree: mode.tree, root, level, side, hue, mindmap, kids: vec![] });
394	                if level == 0 {
395	                    let tb = mode.tree;
396	                    st.boxes[tb].roots.push(i);
397	                } else if let Some(t) = st.topics.get_mut(&parent) {
398	                    t.kids.push(i);
399	                }
400	                st.frames.push(Frame { node: i, mode: child, k: 0, n: cn, hoisted: false, drop_routing: false });
401	                return;
402	            }
403	        }
404	        // a tree container?
405	        if crate::table::is_table(chain) || chain_has(chain, "page") {
406	            return;
407	        }
408	        let layout = own(ns.style.as_ref(), "layout");
409	        let kids: &[Stmt] = ns.children.as_deref().unwrap_or(&[]);
410	        let explicit = match layout.as_deref() {
411	            Some("tree") => true,
412	            Some(_) => return,
413	            None => {
414	                if is_mm || !kids.iter().any(|s| is_mindmap_stmt(b, s)) {
415	                    return;
416	                }
417	                false
418	            }
419	        };
420	        let mindmaps = explicit && kids.iter().any(|s| is_mindmap_stmt(b, s));
421	        let own_dir = own(ns.style.as_ref(), "direction");
422	        let mut hoisted = false;
423	        let dir = if explicit && !(mindmaps && own_dir.is_none()) {
424	            own_dir.clone().unwrap_or_else(|| "column".into())
425	        } else if explicit {
426	            hoisted = true;
427	            mindmap_dir(b, kids).unwrap_or_else(|| "bilateral".into())
428	        } else if let Some(d) = own_dir.clone() {
429	            d
430	        } else {
431	            hoisted = true;
432	            mindmap_dir(b, kids).unwrap_or_else(|| "bilateral".into())
433	        };
434	        // a mindmap's routing goes to a container without its own
435	        let routing = if !explicit && own(ns.style.as_ref(), "routing").is_none() { mindmap_routing(b, kids) } else { None };
436	        container_decls(&mut n.inline, explicit, &dir, mindmaps, routing.as_deref());
437	        let tree = new_box(&mut st, i, &dir);
438	        let mode = Mode { mindmap: !explicit, dir, level: 0, side: None, hue: None, tree, in_mm: false };
439	        let cn = kids.iter().filter(|s| tree_stmt(b, s, &mode)).count();
440	        st.frames.push(Frame { node: i, mode, k: 0, n: cn, hoisted, drop_routing: routing.is_some() });
441	    });
442	}
443	
444	// After a node's content is built: close its frame; a topic's branch wires
445	// follow it in its parent (the scene's own wait for the end).
446	pub fn leave(b: &mut Builder, i: usize) {
447	    let closing = ST.with(|s| {
448	        let mut st = s.borrow_mut();
449	        if st.frames.last().map(|f| f.node) == Some(i) {
450	            st.frames.pop();
451	            true
452	        } else {
453	            false
454	        }
455	    });
456	    if !closing || !is_topic_node(i) {
457	        return;
458	    }
459	    let parent = b.nodes[i].parent.unwrap_or(0);
460	    if parent == 0 {
461	        ST.with(|s| s.borrow_mut().deferred.push(Pending { topic: i }));
462	        return;
463	    }
464	    emit_branches(b, i);
465	}
466	
467	// The scene's own branch wires close the document.
468	pub fn finish(b: &mut Builder) {
469	    let pend = ST.with(|s| {
470	        let mut st = s.borrow_mut();
471	        st.frames.clear();
472	        std::mem::take(&mut st.deferred)
473	    });
474	    for p in pend {
475	        emit_branches(b, p.topic);
476	    }
477	}
478	
479	fn emit_branches(b: &mut Builder, i: usize) {
480	    let Some(t) = topic(i) else { return };
481	    if t.kids.is_empty() {
482	        return;
483	    }
484	    let dir = ST.with(|s| s.borrow().boxes[t.tree].dir.clone());
485	    let kid_info: Vec<(usize, Option<String>, Option<String>)> = t
486	        .kids
487	        .iter()
488	        .map(|&k| {
489	            let kt = topic(k).unwrap();
490	            (k, kt.side, kt.hue)
491	        })
492	        .collect();
493	    // statements: (from side, to side, members, hue class)
494	    let mut stmts: Vec<(&str, &str, Vec<usize>, Option<String>)> = Vec::new();
495	    let all: Vec<usize> = t.kids.clone();
496	    if t.mindmap && dir != "bilateral" {
497	        let (f, to) = if dir == "row" { ("right", "left") } else { ("bottom", "top") };
498	        if t.level == 0 {
499	            for (k, _, h) in &kid_info {
500	                stmts.push((f, to, vec![*k], h.clone()));
501	            }
502	        } else {
503	            stmts.push((f, to, all, t.hue.clone()));
504	        }
505	    } else {
506	        match dir.as_str() {
507	            "column" => stmts.push(("bottom", "top", all, None)),
508	            "row" => stmts.push(("right", "left", all, None)),
